// The cut of PR 7d (plan section 4.5, the config cut and the limits cut): every key of config/config.json that
// leaves the settings, its group (one commit each), what it becomes and its production value. `constant`: a named
// constant in the module that reads it, with that value. `code`: a completed rollout flag on in production, whose
// code always runs. `gone`: a flag off in production or a knob of a dead heuristic, whose code goes with it. `cap`: a
// daily cap of plan section 4.5, gone with its counter. `discord`: a key of the Discord package's own settings,
// interfaces/discord/config.json. `rename`: a privacy switch kept under the name `to`. `wildcard`: a per-wake budget
// kept as one entry `to` for every wake kind. `PRODUCTION_LAYER` is a local layer shaped like production's: the same
// keys set, with synthetic ids, paths and word lists. Nothing here is read from a real local layer.

export const CUT_GROUPS = [
  'features',
  'context',
  'recall',
  'memory',
  'inner life',
  'media and diary',
  'web',
  'llm and models',
  'the rest',
] as const;
export type CutGroup = (typeof CUT_GROUPS)[number];
export type CutFate = 'constant' | 'code' | 'gone' | 'cap' | 'discord' | 'rename' | 'wildcard';
export type CutRow = { key: string; group: CutGroup; becomes: CutFate; production: unknown; to?: string };

